"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[929],{929:(e,n,i)=>{i.r(n),i.d(n,{content:()=>a,description:()=>t,title:()=>s});i(43);var r=i(579);const s="Eine kurze Geschichte von WhimsyLabs: Von unserem bescheidenen Anfang zu einem BETT 2025 Gewinner",t="Wie WhimsyLabs, gegr\xfcndet von Marisa French, STEM-Herausforderungen mit vollst\xe4ndig simulierten Laboren, wirkungsvollen Partnerschaften und preisgekr\xf6nter Innovation angeht.",a=(0,r.jsxs)("div",{children:[(0,r.jsx)("p",{children:"WhimsyLabs wurde urspr\xfcnglich 2020 von Marisa French gegen Ende ihrer Physik-Promotion gegr\xfcndet, gerade als die Pandemie zu treffen begann. Die verheerenden Auswirkungen von COVID-19, die traditionelle Laborumgebungen schlossen, lie\xdfen viele Studenten jahrelang ohne Zugang zu praktischer wissenschaftlicher Bildung. Dies, gekoppelt mit dem R\xfcckgang der STEM-Rankings des Vereinigten K\xf6nigreichs, wobei das UK auf den 15. Platz in den OECD Programme for International Student Assessment (PISA) Wissenschafts-Rankings fiel, hob eine Krise f\xfcr die britische Bildung hervor, die sich pers\xf6nlich anf\xfchlte, da Marisa inspiriert worden war, Wissenschaft zu verfolgen aufgrund der Praktika, die sie in der Sekundarschule erlebt hatte."}),(0,r.jsx)("p",{children:"Angetrieben von dem Wunsch, bedeutsamen Wandel zu schaffen, nutzte Marisa ihre Simulations- und Gaming-F\xe4higkeiten, um ein vollst\xe4ndig simuliertes Sandbox-Virtual-Labor zu entwickeln. Forschung zeigt, dass simulationsbasierte Lernumgebungen das Studentenengagement und die Lernergebnisse erheblich verbessern k\xf6nnen, besonders in STEM-Bereichen, wo praktisches Experimentieren entscheidend ist. Dieses Labor wurde entworfen, um eine sichere, zug\xe4ngliche und ansprechende Umgebung f\xfcr praktisches Lernen zu sein, ohne die Risiken oder Kosten, die mit traditionellen Laboren verbunden sind. Das Ziel war einfach; ein virtuelles Labor zu schaffen, das vollst\xe4ndig den Spa\xdf einfing, den sie in ihren Schullaboren erlebt hatte, und das von jedem, \xfcberall, jederzeit genutzt werden konnte."}),(0,r.jsx)("img",{src:"/images/oldLab.png",alt:"Erstes Mockup-Labor",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Das erste Labor-Mockup: Ein einfacher Prototyp zur Konzeptualisierung der Vision f\xfcr WhimsyLabs."}),(0,r.jsx)("p",{children:"Die Reise begann bescheiden mit einem rudiment\xe4ren Labor-Mockup, das dazu diente, erste Programmierideen zu testen. Von Anfang an war der Traum eines einheitlichen virtuellen Labors klar, aber der Weg zur Verwirklichung war weniger klar. Mit akademischen Simulationen als Grundlage war die erste Laborversion ein einfacher Prototyp, der das Fundament legte, um Ideen zu testen und die Vision zu verfeinern. Da jedoch die meisten akademischen Simulationen Supercomputer verwenden und Monate zum Laufen brauchen, bestand die Herausforderung darin, die Simulationen in Echtzeit auf einer ma\xdfgeschneiderten VR-Plattform laufen zu lassen."}),(0,r.jsx)("p",{children:"Der gr\xf6\xdfte Teil der Arbeit wurde getan, um diese Gleichungen zu verfeinern, damit sie in Echtzeit laufen, w\xe4hrend sie immer noch realistische Ergebnisse produzieren. Das erste Labor war rein ein Machbarkeitsnachweis, der zeigte, dass die Simulationen in Echtzeit laufen konnten und dass sie auf bedeutsame Weise interagiert werden konnten. Studien in der computergest\xfctzten Physikbildung heben die Bedeutung von Echtzeit-Interaktion f\xfcr konzeptionelles Verst\xe4ndnis hervor, da sofortiges Feedback Studenten hilft, theoretische Konzepte mit beobachtbaren Ph\xe4nomenen zu verbinden."}),(0,r.jsx)("p",{children:"Um diese Zeit erregte WhimsyLabs die Aufmerksamkeit der Universit\xe4t Edinburgh aufgrund unserer bahnbrechenden Arbeit in Simulationen und ehrgeizigen wirkungsorientierten Zielen, sicherte Pl\xe4tze in ihren prestigetr\xe4chtigen Inkubatorprogrammen und gewann den Summer Accelerator. Aus diesen Siegen und Anerkennungen konnten wir unsere erste Finanzierungsrunde sichern, um eine ma\xdfgeschneiderte VR/Web-Kombiplattform zu bauen und unseren zweiten Gr\xfcnder zu gewinnen, um beim Aufbau des Labors zu helfen; einen Chemiker-PhD mit jahrelanger Erfahrung in Bildung und Ausbildung f\xfcr die chemische Industrie."}),(0,r.jsx)("img",{src:"/images/testLab.png",alt:"Zweites Tech-Test-Labor",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Das zweite Labor: Ein Testgel\xe4nde f\xfcr fortschrittliche Simulationstechnologien."}),(0,r.jsx)("p",{children:"Das zweite Labor wurde gebaut, um zu sehen, wie wir das Labor mehr wie ein echtes Labor und weniger wie ein Videospiel f\xfchlen lassen konnten. Dies war das erste Mal, dass wir ber\xfccksichtigen mussten, wie das Labor in einer echten Bildungsumgebung verwendet werden w\xfcrde, um die Bewegungen und Aktionen eines Labors zu lehren. Diese Ph\xe4nomenologie des Labors erwies sich als entscheidend f\xfcr Studenten, um das Muskelged\xe4chtnis aufzubauen, das ben\xf6tigt wird, um diese Verfahren im echten Leben durchzuf\xfchren, mit Dingen wie Fl\xfcssigkeitsphysik und realistischen physischen Interaktionen, die ben\xf6tigt werden, um das Gef\xfchl zu erfassen, in einem Labor zu sein. Forschung in verk\xf6rperter Kognition zeigt, dass physische Bewegungen und Gesten das Lernen und die Retention in wissenschaftlichen Kontexten erheblich verbessern."}),(0,r.jsx)("p",{children:"Das zweite Labor war ein Erfolg, und wir konnten Schulen erreichen, um das Labor in einer echten Bildungsumgebung zu testen. Das Feedback war \xfcberw\xe4ltigend positiv, wobei Studenten und Lehrer gleicherma\xdfen das Labor f\xfcr seinen Realismus und seine Benutzerfreundlichkeit lobten. Dies war ein kritischer Schritt in der Entwicklung des Labors, da es zeigte, dass das Labor in einer echten Bildungsumgebung verwendet werden konnte und dass es ein wertvolles Werkzeug f\xfcr Lehren und Lernen sein konnte. Es gab nur ein Problem: das Labor war h\xe4sslich."}),(0,r.jsx)("img",{src:"/images/finalLab.png",alt:"Finales Labordesign",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Das finale Labor: Eine Mischung aus modernster Technologie und einladendem Design, das hervorsticht."}),(0,r.jsx)("p",{children:"Mit diesem im Hinterkopf machten wir uns daran, das Labor von Grund auf komplett neu zu gestalten. Aufgrund der begrenzten Leistung von VR-Headsets und der Verarbeitungskosten der fortschrittlichen Simulationen gab es jedoch wenig Raum, um hochaufl\xf6senden Realismus zu reflektieren. Eine weitere \xdcberlegung war die breite Altersrange, die das Labor nutzen w\xfcrde, von 5 bis 18+, und die Notwendigkeit, das Labor f\xfcr alle zug\xe4nglich zu machen. Die Richtungswahl war schwierig, aber am Ende wurden wir von einem unserer urspr\xfcnglichen W\xfcnsche geleitet, dass das Labor ein Ort des Staunens und der Erkundung ist und dass es ein Ort sein sollte, zu dem Studenten zur\xfcckkehren wollen. Forschung in der Bildungspsychologie betont die Bedeutung intrinsischer Motivation und neugiergetriebenem Lernen in der STEM-Bildung. Um diese Zeit entschieden wir uns f\xfcr unsere Whimsycat als unser Logo und Maskottchen, ein Icon wie kein anderes im virtuellen Laborbereich, das die Neugier und das Staunen verk\xf6rpert, das wir in unseren Studenten inspirieren wollten."}),(0,r.jsx)("p",{children:"Das finale Labordesign war eine Mischung aus modernster Technologie und einladendem Design, das im \xfcberf\xfcllten Edtech-Bereich hervorsticht. Dieses Labor, unser aktuelles Flaggschiff-Labor, war nun eine vollst\xe4ndig realisierte virtuelle Umgebung, die eine breite Palette von Experimenten und Simulationen \xfcber Chemie, Physik und Biologie hinweg anbot. Mit diesem Labor konnten wir an der prestigetr\xe4chtigen Converge Challenge teilnehmen, einem Wettbewerb f\xfcr die besten neuen Unternehmen in Schottland, und einen Platz im Finale unter der Kategorie Create Change sichern, wo wir den zweiten Platz unter allen Unternehmen in Schottland belegten."}),(0,r.jsx)("p",{children:"Durch unseren Sieg bei Converge sicherten wir uns die Mittel, um an der BETT UK teilzunehmen und unsere Innovationen auf eine globale B\xfchne zu bringen. Das Feedback von Studenten und P\xe4dagogen gleicherma\xdfen war \xfcberw\xe4ltigend positiv, wobei viele hervorhoben, wie die Plattform die STEM-Bildung transformiert. Zus\xe4tzlich war WhimsyLabs' innovativer Ansatz nicht unbemerkt geblieben. Die Plattform wurde vom Epping Forest Schools Partnership Trust als Teil der Kids Judge Bett anerkannt, wo Sch\xfcler WhimsyLabs f\xfcr ihre Nutzung virtueller Labore nominierten, um Studenten \xfcber Laborumgebungen zu unterrichten, w\xe4hrend sie auch ein m\xe4chtiges Werkzeug f\xfcr Nachhaltigkeit bereitstellten. Diese Anerkennung hebt die Kraft unserer Mission hervor, die n\xe4chste Generation von STEM-F\xfchrungskr\xe4ften zu inspirieren."}),(0,r.jsx)("p",{children:"W\xe4hrend WhimsyLabs in den letzten Jahren still seine Technologie entwickelt hat, nur gefl\xfcstert unter einigen Pilotschulen, sind wir nun bereit, L\xe4rm zu machen und laut \xfcber unsere bahnbrechende L\xf6sung zu sein. Mit einem starken Fundament, einem wachsenden Team und einer bew\xe4hrten Erfolgsbilanz der Innovation ist WhimsyLabs bereit, die wissenschaftliche Bildung zu transformieren und die n\xe4chste Generation von STEM-F\xfchrungskr\xe4ften zu inspirieren, w\xe4hrend wir unseren Kernwerten treu bleiben. Ein Sandbox-Labor bereitzustellen, das die Physikalit\xe4t der Durchf\xfchrung von Laboren erfasst, den Spa\xdf und das Staunen der Wissenschaft zu erfassen und den Zugang zu Premium-Wissenschaftsbildungstechnologie f\xfcr alle Institutionen weltweit zu demokratisieren."})]})}}]);
